python.code:
def countdown(n):
    if n == 0:
        return ['go']
    return [n] + countdown(n - 1)

print(countdown(3))

javascript.code:
function deepSum(items) {
  let total = 0
  for (const item of items) {
    total += Array.isArray(item) ? deepSum(item) : item
  }
  return total
}
console.log(deepSum([1, [2, [3, 4]], 5]))

typescript.code:
type Nested = number | Nested[]

function deepSum(items: Nested[]): number {
  let total = 0
  for (const item of items) {
    total += Array.isArray(item) ? deepSum(item) : item
  }
  return total
}
console.log(deepSum([1, [2, [3, 4]], 5]))

python.code:
def deep_sum(items):
    total = 0
    for item in items:
        total += deep_sum(item) if isinstance(item, list) else item
    return total

print(deep_sum([1, [2, [3, 4]], 5]))

javascript.code:
const memo = new Map()
function fib(n) {
  if (n < 2) return n
  if (memo.has(n)) return memo.get(n)
  const result = fib(n - 1) + fib(n - 2)
  memo.set(n, result)
  return result
}
console.log(fib(50))

typescript.code:
const memo = new Map<number, number>()
function fib(n: number): number {
  if (n < 2) return n
  if (memo.has(n)) return memo.get(n)!
  const result = fib(n - 1) + fib(n - 2)
  memo.set(n, result)
  return result
}
console.log(fib(50))

python.code:
memo = {}

def fib(n):
    if n < 2:
        return n
    if n not in memo:
        memo[n] = fib(n - 1) + fib(n - 2)
    return memo[n]

print(fib(50))
